def cite_map():
    return {key: i for i, (key, _) in enumerate(SOURCES, 1)}


def sub(text: str) -> str:
    numbers = cite_map()
    for key, num in numbers.items():
        text = text.replace(f"@@{key}@@", f"[{num}]")
    if "@@" in text:
        raise SystemExit(f"Неподставленная ссылка: {text[text.find('@@'):text.find('@@')+20]}")
    return text.replace(" — ", "\u00a0— ")


def _rfonts(run, name=FONT, size=14, bold=False, italic=False):
    run.font.name = name
    run.font.size = Pt(size)
    run.bold = bold
    run.italic = italic
    run.font.color.rgb = RGBColor(0, 0, 0)
    rpr = run._element.get_or_add_rPr()
    rfonts = rpr.find(qn("w:rFonts"))
    if rfonts is None:
        rfonts = OxmlElement("w:rFonts")
        rpr.append(rfonts)
    for attr in ("w:ascii", "w:hAnsi", "w:cs", "w:eastAsia"):
        rfonts.set(qn(attr), name)
    lang = rpr.find(qn("w:lang"))
    if lang is None:
        lang = OxmlElement("w:lang")
        rpr.append(lang)
    lang.set(qn("w:val"), "ru-RU")
    lang.set(qn("w:eastAsia"), "ru-RU")


def _spacing(p, before=0, after=0, line=1.5, indent=1.25, align="justify", keep_next=False, page_break=False):
    pf = p.paragraph_format
    pf.space_before = Pt(before)
    pf.space_after = Pt(after)
    pf.line_spacing = line
    pf.line_spacing_rule = WD_LINE_SPACING.MULTIPLE if line else WD_LINE_SPACING.SINGLE
    pf.first_line_indent = Cm(indent) if indent else Cm(0)
    pf.widow_control = True
    if align == "justify":
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    elif align == "center":
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    elif align == "left":
        p.alignment = WD_ALIGN_PARAGRAPH.LEFT
    elif align == "right":
        p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    if keep_next:
        pf.keep_together = True
        pf.keep_with_next = True
    if page_break:
        pf.page_break_before = True


def _add_text(p, text, size=14, bold=False, italic=False):
    # Простая разметка: {b}...{/b} и {i}...{/i}, без вложенности.
    parts = []
    buf = ""
    mode = "n"
    i = 0
    while i < len(text):
        if text.startswith("{b}", i):
            parts.append((buf, mode))
            buf = ""
            mode = "b"
            i += 3
        elif text.startswith("{/b}", i):
            parts.append((buf, mode))
            buf = ""
            mode = "n"
            i += 4
        elif text.startswith("{i}", i):
            parts.append((buf, mode))
            buf = ""
            mode = "i"
            i += 3
        elif text.startswith("{/i}", i):
            parts.append((buf, mode))
            buf = ""
            mode = "n"
            i += 4
        else:
            buf += text[i]
            i += 1
    parts.append((buf, mode))
    for chunk, kind in parts:
        if not chunk:
            continue
        run = p.add_run(chunk)
        _rfonts(
            run,
            size=size,
            bold=bold or kind == "b",
            italic=italic or kind == "i",
        )


def _page_field(paragraph, size=12):
    run = paragraph.add_run()
    _rfonts(run, size=size)
    begin = OxmlElement("w:fldChar")
    begin.set(qn("w:fldCharType"), "begin")
    instr = OxmlElement("w:instrText")
    instr.set(qn("xml:space"), "preserve")
    instr.text = " PAGE "
    end = OxmlElement("w:fldChar")
    end.set(qn("w:fldCharType"), "end")
    run._r.append(begin)
    run._r.append(instr)
    run._r.append(end)


def _set_run_spacing(run, twips):
    rpr = run._element.get_or_add_rPr()
    sp = rpr.find(qn("w:spacing"))
    if sp is None:
        sp = OxmlElement("w:spacing")
        rpr.append(sp)
    sp.set(qn("w:val"), str(twips))


class Paper:
    def __init__(self, figs, toc_pages):
        self.figs = figs
        self.toc_pages = toc_pages
        self.toc = []
        self.doc = Document()
        self._setup()

    def _setup(self):
        sec = self.doc.sections[0]
        sec.page_width = Cm(21.0)
        sec.page_height = Cm(29.7)
        sec.left_margin = Cm(3.0)
        sec.right_margin = Cm(1.5)
        sec.top_margin = Cm(2.0)
        sec.bottom_margin = Cm(2.0)
        sec.header_distance = Cm(0.8)
        sec.footer_distance = Cm(0.8)
        sec.different_first_page_header_footer = False

        normal = self.doc.styles["Normal"]
        normal.font.name = FONT
        normal.font.size = Pt(14)
        normal.font.color.rgb = RGBColor(0, 0, 0)
        rpr = normal.element.get_or_add_rPr()
        rfonts = rpr.find(qn("w:rFonts"))
        if rfonts is None:
            rfonts = OxmlElement("w:rFonts")
            rpr.append(rfonts)
        for attr in ("w:ascii", "w:hAnsi", "w:cs", "w:eastAsia"):
            rfonts.set(qn(attr), FONT)
        pf = normal.paragraph_format
        pf.line_spacing = 1.5
        pf.space_after = Pt(0)
        pf.space_before = Pt(0)
        pf.first_line_indent = Cm(1.25)

        settings = self.doc.settings.element
        auto = OxmlElement("w:autoHyphenation")
        auto.set(qn("w:val"), "false")
        settings.append(auto)
        upd = OxmlElement("w:updateFields")
        upd.set(qn("w:val"), "true")
        settings.append(upd)

        core = self.doc.core_properties
        core.title = "Методика формирования знаний о причинно-следственных связях"
        core.subject = "Теория и методика обучения и воспитания географии"
        core.language = "ru-RU"
        core.category = "Курсовая работа"

        # Титул и задание — раздел без колонцифры. Номера полей совпадут
        # с физическими страницами, потому что содержание начнётся с 3.
        footer = sec.footer
        footer.is_linked_to_previous = False
        footer.paragraphs[0].text = ""
        # Пустой абзац, который Document() создаёт сам, съедает место на титуле.
        body = self.doc.element.body
        first = body.find(qn("w:p"))
        if first is not None and not first.findall(".//" + qn("w:t")):
            body.remove(first)

    def _new_section(self):
        sec = self.doc.add_section()
        sec.page_width = Cm(21.0)
        sec.page_height = Cm(29.7)
        sec.left_margin = Cm(3.0)
        sec.right_margin = Cm(1.5)
        sec.top_margin = Cm(2.0)
        sec.bottom_margin = Cm(2.0)
        sec.header_distance = Cm(0.8)
        sec.footer_distance = Cm(0.8)
        sect_pr = sec._sectPr
        pg = OxmlElement("w:pgNumType")
        pg.set(qn("w:start"), "3")
        sect_pr.append(pg)
        footer = sec.footer
        footer.is_linked_to_previous = False
        p = footer.paragraphs[0]
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p.paragraph_format.first_line_indent = Cm(0)
        p.paragraph_format.space_before = Pt(0)
        p.paragraph_format.space_after = Pt(0)
        _page_field(p, 12)
        header = sec.header
        header.is_linked_to_previous = False
        header.paragraphs[0].text = ""
        return sec

    def p(self, text, size=14, bold=False, italic=False, align="justify", indent=1.25,
          before=0, after=0, line=1.15, keep_next=False, page_break=False):
        par = self.doc.add_paragraph()
        _spacing(par, before, after, line, indent, align, keep_next, page_break)
        _add_text(par, sub(text), size=size, bold=bold, italic=italic)
        return par

    def h1(self, text, toc=True, page_break=False):
        shown = sub(text)
        if toc:
            self.toc.append((1, shown))
        par = self.doc.add_paragraph()
        _spacing(par, before=0, after=10, line=1.15, indent=0, align="center",
                 keep_next=True, page_break=page_break)
        _add_text(par, shown, size=16, bold=True)
        return par

    def h2(self, text):
        shown = sub(text)
        self.toc.append((2, shown))
        par = self.doc.add_paragraph()
        _spacing(par, before=10, after=4, line=1.15, indent=0, align="left", keep_next=True)
        _add_text(par, shown, size=14, bold=True)
        return par

    def item(self, text):
        return self.p(text, indent=1.25)

    def quote(self, text):
        return self.p(text, italic=True, indent=1.25, before=6, after=6)

    def note(self, text):
        par = self.doc.add_paragraph()
        _spacing(par, before=6, after=6, line=1.15, indent=1.25, align="justify")
        run = par.add_run("Примечание")
        _rfonts(run, size=12, bold=True)
        _set_run_spacing(run, 40)
        run2 = par.add_run(" — " + sub(text))
        _rfonts(run2, size=12)
        return par

    def caption_table(self, text):
        par = self.doc.add_paragraph()
        _spacing(par, before=12, after=4, line=1.15, indent=0, align="left", keep_next=True)
        run = par.add_run("Таблица")
        _rfonts(run, size=14, bold=True)
        _set_run_spacing(run, 60)
        # Номер и название — обычным шрифтом, как требует пример в стандарте:
        # слово «Таблица» разрежено, дальше номер и наименование через тире.
        rest = sub(text)
        # text приходит уже с номером: " 1 — Название" или "1 — Название"
        if not rest.startswith(" "):
            rest = " " + rest
        run2 = par.add_run(rest)
        _rfonts(run2, size=14)
        return par

    def caption_fig(self, text):
        par = self.doc.add_paragraph()
        _spacing(par, before=4, after=12, line=1.15, indent=0, align="center")
        _add_text(par, sub(text), size=14)
        return par

    def figure(self, key, caption, width=15.4):
        par = self.doc.add_paragraph()
        _spacing(par, before=8, after=2, line=1.0, indent=0, align="center", keep_next=True)
        run = par.add_run()
        run.add_picture(str(self.figs[key]), width=Cm(width))
        self.caption_fig(caption)

    def table(self, caption, headers, rows, widths=None):
        self.caption_table(caption)
        tbl = self.doc.add_table(rows=1 + len(rows), cols=len(headers))
        tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
        tbl.autofit = False
        tbl.allow_autofit = False
        tbl_pr = tbl._tbl.tblPr
        borders = OxmlElement("w:tblBorders")
        for edge in ("top", "left", "bottom", "right", "insideH", "insideV"):
            el = OxmlElement(f"w:{edge}")
            el.set(qn("w:val"), "single")
            el.set(qn("w:sz"), "4")
            el.set(qn("w:space"), "0")
            el.set(qn("w:color"), "000000")
            borders.append(el)
        tbl_pr.append(borders)
        tbl_w = OxmlElement("w:tblW")
        tbl_w.set(qn("w:w"), "5000")
        tbl_w.set(qn("w:type"), "pct")
        tbl_pr.append(tbl_w)
        jc = tbl_pr.find(qn("w:jc"))
        if jc is None:
            jc = OxmlElement("w:jc")
            tbl_pr.append(jc)
        jc.set(qn("w:val"), "center")

        if widths is None:
            widths = [16.5 / len(headers)] * len(headers)

        def fill(cell, text, header=False):
            cell.text = ""
            p = cell.paragraphs[0]
            _spacing(p, before=0, after=0, line=1.0, indent=0, align="left")
            _add_text(p, sub(text), size=12, bold=header)
            tc = cell._tc
            tc_pr = tc.get_or_add_tcPr()
            mar = OxmlElement("w:tcMar")
            for name, val in (("top", "40"), ("left", "60"), ("bottom", "40"), ("right", "60")):
                node = OxmlElement(f"w:{name}")
                node.set(qn("w:w"), val)
                node.set(qn("w:type"), "dxa")
                mar.append(node)
            tc_pr.append(mar)
            if header:
                shd = OxmlElement("w:shd")
                shd.set(qn("w:val"), "clear")
                shd.set(qn("w:color"), "auto")
                shd.set(qn("w:fill"), "E6E6E6")
                tc_pr.append(shd)

        for j, h in enumerate(headers):
            fill(tbl.rows[0].cells[j], h, True)
        hdr_tr = tbl.rows[0]._tr.get_or_add_trPr()
        hdr_tr.append(OxmlElement("w:tblHeader"))
        for i, row in enumerate(rows, 1):
            for j, val in enumerate(row):
                fill(tbl.rows[i].cells[j], val, False)
            tr_pr = tbl.rows[i]._tr.get_or_add_trPr()
            tr_pr.append(OxmlElement("w:cantSplit"))
        # ширины
        for row in tbl.rows:
            for j, w in enumerate(widths):
                row.cells[j].width = Cm(w)
        self.p("", size=6, indent=0, before=0, after=0, line=1.0)

    def toc_page(self):
        self.h1("Содержание", toc=False, page_break=False)
        # Позиция правого табулятора — ширина текстового поля 16,5 см.
        pos = str(int(16.5 * 567))
        for level, title in self.toc:
            key = title
            page = self.toc_pages.get(key, "…")
            par = self.doc.add_paragraph()
            left = 0 if level == 1 else 0.75
            _spacing(par, before=2, after=2, line=1.15, indent=0, align="left")
            par.paragraph_format.left_indent = Cm(left)
            ppr = par._p.get_or_add_pPr()
            tabs = OxmlElement("w:tabs")
            tab = OxmlElement("w:tab")
            tab.set(qn("w:val"), "right")
            tab.set(qn("w:leader"), "dot")
            tab.set(qn("w:pos"), pos)
            tabs.append(tab)
            ppr.append(tabs)
            _add_text(par, title, size=14, bold=(level == 1))
            run = par.add_run("\t" + str(page))
            _rfonts(run, size=14, bold=(level == 1))

    def bibliography(self):
        self.h1("Список использованных источников", page_break=True)
        self.p(
            "Список составлен в алфавитном порядке. Нормативные документы и электронные материалы поставлены на своё место по первому слову описания, а не вынесены вперёд отдельным блоком.",
            indent=1.25,
        )
        for i, (_, text) in enumerate(SOURCES, 1):
            par = self.doc.add_paragraph()
            _spacing(par, before=0, after=2, line=1.0, indent=0, align="justify")
            par.paragraph_format.left_indent = Cm(0.75)
            par.paragraph_format.first_line_indent = Cm(-0.75)
            _add_text(par, f"{i}  {text}", size=12)

    def save(self, path):
        self.doc.save(path)


def write_title(doc: Paper):
    d = doc
    d.p("МИНИСТЕРСТВО ПРОСВЕЩЕНИЯ РОССИЙСКОЙ ФЕДЕРАЦИИ", size=12, bold=True,
        align="center", indent=0, line=1.0, before=0, after=2)
    d.p("Федеральное государственное бюджетное образовательное", size=12,
        align="center", indent=0, line=1.0)
    d.p("учреждение высшего образования", size=12, align="center", indent=0, line=1.0, after=2)
    d.p("________________________________________________________________", size=14,
        align="center", indent=0, line=1.0, before=6)
    d.p("(наименование образовательной организации)", size=12, italic=True,
        align="center", indent=0, line=1.0, after=8)
    d.p("Факультет _______________________________________________", size=14,
        align="center", indent=0, line=1.0, before=4)
    d.p("Кафедра _________________________________________________", size=14,
        align="center", indent=0, line=1.0, before=2, after=10)
    d.p("КУРСОВАЯ РАБОТА", size=16, bold=True, align="center", indent=0, line=1.0, before=18, after=8)
    d.p("по дисциплине", size=14, align="center", indent=0, line=1.0)
    d.p("«Теория и методика обучения и воспитания географии»", size=14, bold=True,
        align="center", indent=0, line=1.0, after=8)
    d.p("на тему", size=14, align="center", indent=0, line=1.0)
    d.p("«Методика формирования знаний о причинно-следственных связях", size=14, bold=True,
        align="center", indent=0, line=1.15)
    d.p("на примере системы гидрологических знаний", size=14, bold=True,
        align="center", indent=0, line=1.15)
    d.p("в курсах 7 и 8 классов»", size=14, bold=True,
        align="center", indent=0, line=1.15, after=16)

    # Блок подписей — таблица без границ, чтобы строки не расползались.
    tbl = d.doc.add_table(rows=6, cols=2)
    tbl.autofit = False
    data = [
        ("", "Выполнил(а):"),
        ("", "студент(ка) ______ курса"),
        ("", "группы _______________"),
        ("", "________________ / _____________ /"),
        ("", ""),
        ("", "Научный руководитель:"),
    ]
    for i, (a, b) in enumerate(data):
        for j, val in enumerate((a, b)):
            cell = tbl.rows[i].cells[j]
            cell.text = ""
            p = cell.paragraphs[0]
            _spacing(p, 0, 0, 1.0, 0, "left" if j == 0 else "left")
            _add_text(p, val, size=14)
    # вторая порция руководителя
    d.p("учёная степень, должность ___________________________", size=14, indent=0, align="right", line=1.0, before=0)
    d.p("________________ / _____________ /", size=14, indent=0, align="right", line=1.0, before=2, after=8)
    d.p("Город", size=14, align="center", indent=0, line=1.0, before=16)
    d.p("2026", size=14, align="center", indent=0, line=1.0, before=0)


def write_task(doc: Paper):
    d = doc
    d.h1("Задание на курсовую работу", toc=False, page_break=True)
    d.p("Студенту ________________________________  группы ________________", indent=0, line=1.15, before=6)
    d.p("{b}1 Тема:{/b} Методика формирования знаний о причинно-следственных связях на примере системы гидрологических знаний в курсах 7 и 8 классов.", indent=0, line=1.15, before=8)
    d.p("{b}2 Исходные данные к работе.{/b} Федеральный государственный образовательный стандарт основного общего образования (приказ Минпросвещения России от 31.05.2021 № 287). Федеральная рабочая программа по географии в составе федеральной образовательной программы основного общего образования (приказ от 18.05.2023 № 370). Учебники географии 7 и 8 классов действующих линий. Литература по методике обучения географии, возрастной педагогике и общей гидрологии.", indent=0, line=1.15, before=6)
    d.p("{b}3 Перечень вопросов, подлежащих разработке.{/b}", indent=0, line=1.15, before=6)
    for line in [
        "3.1 Теоретические основы знаний о причинно-следственных связях в школьной географии и условия их усвоения в 13–15 лет.",
        "3.2 Система гидрологических знаний в курсах 7 и 8 классов, типы связей и преемственность с 6 классом.",
        "3.3 Методика формирования этих знаний: этапы, приёмы, задания, диагностика, фрагмент урока.",
    ]:
        d.p(line, indent=0, line=1.15, before=2)
    d.p("{b}4 Перечень графического материала.{/b} Рисунки 1–8 (схемы связей, преемственности, хода стока). Таблицы 1–8. Приложения А и Б: технологическая карта урока и диагностические задания.", indent=0, line=1.15, before=6)
    d.p("{b}5 Срок сдачи студентом законченной работы:{/b} «____» ________________ 2026 г.", indent=0, line=1.15, before=6)
    d.p("{b}6 Дата выдачи задания:{/b} «____» ________________ 2026 г.", indent=0, line=1.15, before=4)
    d.p("Руководитель _________________ / _________________ /", indent=0, line=1.15, before=12)
    d.p("Задание принял к исполнению _________________ / _________________ /", indent=0, line=1.15, before=6)
    d.p("Подписи на листе задания проставляются от руки. Тема, исходные данные и графическая часть соответствуют тексту работы.", indent=0, size=12, line=1.15, before=10)


def write_body(doc: Paper):
    d = doc
    # --- введение ---
    d.h1("Введение", page_break=True)
    d.p("География в 7 и 8 классах уже плохо переживает урок, на котором реку только показывают на карте и записывают в тетрадь длину. Программа ждёт другого ответа. Ученик должен сказать, почему река ведёт себя именно так, и суметь перенести это «почему» на реку, которую вместе ещё не разбирали. В требованиях это написано без особой поэзии. В 6 классе школьник учится связывать питание, режим и климат бассейна. В 7 классе к этому добавляются Мировой океан, течения, солёность и внутренние воды материков «и определяющие их факторы». В 8 классе та же связка проверяется на реках России: сравнить режим и характер течения, объяснить, где возникают наводнения, заторы, сели, и не перепутать причину с соседним фактом @@fgos@@, @@fop@@.")
    d.p("На словах всё гладко, а в классе связь часто не собирается. Номенклатуру Волга, Енисей, Байкал, Амазонка дети называют спокойно. Дальше ответы редеют. «Волга разливается весной, потому что тает снег» — это ещё не цепочка, а её обломок. Почему именно снег, а не летний дождь, почему половодье у Оби тянется долго, зачем Волге водохранилища и при чём тут уровень Каспия, договаривают уже немногие. В 7 классе с Амазонкой бывает та же история: «она полноводная, потому что большая и течёт по лесу». Лес и длина здесь рядом, но не они делают реку такой. Вода берётся из дождей, а ровный ход года связан ещё и с тем, что притоки приходят из разных полушарий.")
    d.p("Отсюда тема работы. Причинно-следственная связь в школьной географии — не украшение сильного ответа и не отдельный пункт, который можно «пройти», если останется время. Без неё гидрология рассыпается на список объектов и круглых цифр. Для методики это как раз удобный материал. Связи короче, чем в географии хозяйства: климат и рельеф лежат на соседних картах, ход стока можно нарисовать, а ошибку ученика слышно сразу. Если он назвал следствием то, что на самом деле было причиной, поправить его можно на этом же уроке, а не «когда-нибудь в 9 классе».")
    d.p("Объект работы — обучение географии в 7 и 8 классах. Предмет — методика формирования знаний о причинно-следственных связях на материале гидрологических знаний. Цель — собрать такую методику для действующей программы и показать, как она выглядит в заданиях и на уроке, а не только в общих словах про «развитие мышления».")
    d.p("Для этого нужно было решить несколько задач. Сначала разобраться, что именно в школьном курсе считают причинно-следственной связью и чем она отличается от перечисления свойств реки. Затем посмотреть, что реально по силам ученику 13–15 лет и какие приёмы умственной работы для этого уже описаны, чтобы не выдумывать «авторскую технологию» из одного приёма. Дальше — вынуть из федеральной программы систему гидрологических знаний 7 и 8 классов и разложить её по типам связей, не забыв 6 класс: без него объяснение в 8 классе начинается с середины. И уже потом предложить этапы урока, задания, типичные сбои и способ проверить, что связь понята, а не заучена фразой из параграфа.")
    d.p("Работа теоретико-методическая. Я опирался на текст стандарта и федеральной программы, на учебники линий, по которым сейчас учат и по которым учили ещё недавно, на пособия по методике географии и на общую гидрологию в том объёме, который нужен учителю, чтобы не сказать в классе лишнего. Отдельный педагогический эксперимент с замерами «до и после» в конкретном 8 «Б» я не проводил и цифры такого опыта здесь не привожу. Задания собраны так, чтобы их можно было взять на практику и уже там увидеть, на какой стрелке цепочки класс останавливается.")
    d.p("Практический смысл, как мне кажется, простой. На тему внутренних вод России программа оставляет около шести часов, на Мировой океан в 7 классе — тоже шесть @@fop@@. За это время нельзя добросовестно «рассказать все реки». Нужен способ: одна цепочка разбирается вслух до конца, остальные ученик читает тем же приёмом. Если такого способа нет, практическая работа превращается в раскрашивание бассейнов, а причинно-следственная связь остаётся в графе планируемых результатов.")
    d.p("Текст состоит из трёх глав, заключения, списка источников и двух приложений. В первой главе — что такое связь в географическом содержании, на что рассчитывать по возрасту и какими приёмами её вообще устанавливают. Во второй — гидрология 7 и 8 классов: что требует программа, какие связи там разные и как они нарастают от 6 класса. В третьей — сама методика, два учебных сюжета (берега материков и реки России), ошибки и проверка. Рисунки не стоят «для количества». На них вынесены цепочки, которые в абзаце тонут.")

    # --- глава 1 ---
    d.h1("1 Теоретические основы формирования знаний о причинно-следственных связях")
    d.h2("1.1 Связь в составе географических знаний")
    d.p("В методике обучения географии содержание курса давно делят не только по темам, но и по виду знания. Одно дело — факт и географическое название. Другое — понятие. Третье — связь, из которой уже вырастает закономерность. Эмпирический слой (факт, номенклатура, представление об объекте) без теоретического слоя курс не держит, и наоборот: закономерность, которую не к чему приложить на карте, повисает @@tam@@, @@dush@@. Для воды это видно буквально на одном уроке. «Река Лена» — номенклатура. «Режим реки» — понятие, и то только если за словами половодье, паводок и межень ученик видит, как сток распределён по году. «Снег копится всю зиму и сходит в начале лета, а низовье ещё подо льдом» — уже связь. «У больших рек Сибири со снеговым питанием половодье смещено на начало лета и часто сопровождается заторами» — закономерность, её можно нести на Колыму и Яну.")
    d.p("Н. Н. Баранский требовал от географического мышления двух вещей сразу: чтобы оно было привязано к территории и чтобы оно не замыкалось в одном компоненте @@bar@@. К гидрологии это подходит почти дословно. Режим Лены нельзя объяснить «вообще», без карты. И нельзя объяснить одним климатом, если река течёт на север, в сторону ещё не вскрывшегося льда, а в бассейне мерзлота. Климат даёт питание, рельеф даёт характер течения и направление, мерзлота отрезает зимнее подземное питание. Уберите карту и оставьте определение из словаря — останется речь не про географию.")
    d.p("В. П. Максаковский собирал географическую культуру из нескольких частей: картины мира, географического мышления, владения методами и языком науки @@maks@@. Умение видеть территориальную связь относится сюда же, это не добавка «для олимпиады». Школьник с хорошей памятью на цифры может знать длину Нила и не понимать, почему паводок приходит в Египет в то время года, когда в Египте почти не идёт дождь. Память при этом в порядке. Не собран как раз тот кусок культуры, который Максаковский связывал с мышлением, а не с начитанностью.")
    d.p("Дальше приходится различать слова, которые в ответе ученика часто слипаются. Причинно-следственная связь — это утверждение вида «А ведёт к Б, потому что…», и его можно проверить встречным вопросом: если убрать А, Б изменится или нет. Рядом стоящее совпадение такой проверки не проходит. Тайга и густая речная сеть в умеренном поясе часто встречаются вместе, но лес не «делает» реку полноводной. Оба следствия климата и увлажнения. Если этого не проговорить, в тетради появляется цепочка «лес → река», и она потом всплывает на Амазонке.")
    d.p("Отдельная вещь — обратная связь, когда следствие начинает влиять на причину. Для 7 класса это ещё редкость, для 8 класса уже честный материал. Болото Западной Сибири не только результат плоского рельефа: само болото ещё сильнее тормозит сток. Водохранилища Волги не отменяют снеговое питание, но срезают пик половодья, и дальше уже этот новый режим влияет на пойму и на то, сколько воды доходит до дельты. Путать слой «природа» и слой «человек поправил природу» нельзя. Иначе любая плотина становится универсальной причиной всего, что ученик видит ниже по течению.")
    d.p("Масштаб тоже ломает правильные фразы. Связь, верная для бассейна, может быть неверной для одного створа. У Нила режим низовья исторически задан Эфиопским нагорьем, а не климатом Сахары, по которой река просто проходит. Такие реки называют транзитными. Если сказать «Нил полноводный, потому что течёт по пустыне», получится географическая нелепость, хотя пустыня на карте действительно лежит вдоль русла. В 8 классе та же ловушка есть у Волги: в низовьях климат суше, а вода пришла с верхней и средней части бассейна.")
    d.figure(
        "levels",
        "Рисунок 1 — Ступени гидрологического знания: от названия реки к переносу объяснения",
    )
    d.p("На рисунке 1 я специально поставил перенос последней ступенью. Пока ученик объясняет только ту реку, про которую только что прочитал абзац, учитель не знает, понята связь или запомнен текст. Это старое требование методики, не придумка ради красивой схемы. Пока знание не сдвинулось на новый объект, оно ещё не стало умением @@kab@@, @@fin@@. Для гидрологии новый объект всегда под рукой: соседняя река того же типа или, наоборот, река, которая похожа по длине и не похожа по питанию. Длина здесь как раз мешает. Дети охотно сравнивают километры, потому что цифра кажется «объективной», и мимо питания проходят.")
    d.p("Есть и языковая путаница, без которой связи не получается уже на уровне слов. В быту «наводнение», «половодье» и «паводок» звучат как одно и то же. В курсе это разные вещи. Половодье — ежегодный высокий подъём, связанный с основным источником питания: снег весной, дожди муссона летом. Паводок — подъём нерегулярный, его может дать ливень. Наводнение — уже бедствие на территории, а не просто высокий уровень в русле. Затор — скопление льда на ледоходе, зажор — забивание русла шугой при ледоставе. Если эти слова не развести в начале темы, все причинные фразы 8 класса расползаются. Ученик честно говорит «наводнение от затора», но сам не понимает, зима это или весна.")

    d.h2("1.2 Что посильно ученику 7–8 класса")
    d.p("Седьмой класс — это чаще всего 13–14 лет, восьмой — 14–15. В учебниках психологии этому возрасту охотно приписывают «теоретическое мышление» целиком. В живом классе картина ровнее и скучнее. Часть детей уже держит в голове цепочку из трёх звеньев и может вернуться по ней назад. Часть по-прежнему думает от картинки: пока климатическая карта и карта рек не лежат рядом, причина не появляется. Опираться на верхнюю границу возраста и обижаться, что «они же уже большие», методика не имеет права. Л. С. Выготский как раз настаивал, что обучение ориентируется не на то, что ребёнок делает уверенно один, а на то, что пока получается вместе со взрослым, — на зону ближайшего развития @@vyg@@. Для нашей темы это очень прикладное замечание.")
    d.p("Цепочка из двух звеньев («зима холодная → к весне много снега») у большинства семиклассников уже в зоне актуального. Цепочка из четырёх-пяти, да ещё с оговоркой «это верно для низовья, а не для истока», чаще лежит в зоне ближайшего. Её имеет смысл собирать на доске общим голосом. Требовать такую фразу «с холодной головы» на самостоятельной в начале темы — значит проверять не связь, а смелость. И получить в ответ либо пустоту, либо одну выученную причину на все случаи.")
    d.p("С понятием та же история. В. В. Давыдов отличал знание существенного отношения от знания набора признаков @@dav@@. «Режим» в школьном определении легко превратить в список: половодье, паводок, межень, ледостав. Список запоминается. Отношение — нет. А существо режима в том, как расход распределён по месяцам и от какого источника воды это зависит. Если источник снег и копится он долго, подъём будет дружным и придёт в тёплый сезон. Если источник летний дождь, картина года другая, хотя слова «половодье» и «межень» формально те же. Пока это отношение не вытащено, определение режима ученик сдаёт и на следующей реке снова отвечает длиной.")
    d.p("Отсюда же понятно, зачем на уроке проблемный вопрос, а не только объяснение учителя. Проблемная ситуация возникает там, где старого знания не хватает на факт, который ребёнок сам видит @@mah@@, @@pon@@. Для 7 класса хорошо работает Австралия. Материк со всех сторон в океане, а постоянных рек в середине почти нет. Бытовая формула «рядом море — значит влажно» ломается. Класс вынужден звать климат, течение у западного берега и хребет, который перехватывает дождь на востоке. Готовая фраза учителя эту развилку закрывает слишком рано. Г. А. Понурова как раз писала проблемный подход в географии не как «вопрос потруднее», а как место, где известного ученику способа объяснения уже не хватает @@pon@@.")
    d.p("И. Я. Лернер раскладывал методы по тому, кто добывает знание @@ler@@. Объяснительно-иллюстративный метод отдаёт готовую связь: учитель сам говорит, почему Амазонка полноводна, класс записывает. Репродуктивный метод заставляет повторить эту связь на похожем объекте почти без изменения. Частично-поисковый оставляет ученику одно звено или выбор фактора. Исследовательский просит собрать цепочку по материалу, которого в параграфе в готовом виде нет. Для 7–8 класса рабочая лошадка — частично-поисковый метод. Чистый рассказ нужен на первом примере, иначе не на что опереться. Полноценное исследование на шесть часов внутренних вод России не встаёт: дети утонут в картах, а режим так и не назовут. Это не отказ от развития. Это отказ изображать исследование там, где задача урока — научить короткому приёму и успеть им воспользоваться дважды.")
    d.p("Е. Н. Кабанова-Меллер полезен здесь тем, что приём умственной работы можно показать отдельно, а не надеяться, что он «сам снимется» с хорошего объяснения @@kab@@. Приём «установить причинно-следственную связь» для географии я бы проговаривал с классом вслух, хотя бы один раз за тему, по шагам. Сначала договариваемся, какой факт объясняем, и не берём весь параграф. Потом называем факторы, которые в принципе бывают у реки: климат, рельеф, человек, мерзлота, озеро выше по течению. Потом смотрим, что из этого видно на картах, а что мы просто любим повторять. Потом выбираем ведущий фактор и честно говорим, если второй фактор его усиливает, а не заменяет. Потом собираем фразу со словом «потому что». И только потом несём приём на другую реку. На рисунке 2 эти шаги разложены так, как их удобно держать на полях учительского конспекта.")
    d.figure(
        "method",
        "Рисунок 2 — Шаги приёма «установить причинно-следственную связь»",
    )
    d.p("У приёма есть потолок, и его лучше знать до того, как схема превратится в ритуал. Подросток держит две причины, иногда три, но не шесть: длинный список «факторов» оставляет в голове первую строчку. Вторая беда — одна причина на все реки. Третья — путаница времени и причины: плотину построили, половодье спало, значит, плотина и есть причина реки. У Волги в этом есть часть правды, но снег никуда не делся. Мотив, если его не засушить, дают не определения, а странные факты: летний Амур, затор, нагон на Неве, вопрос «если бы все притоки Амазонки лежали в одном полушарии». По ответу сразу видно, кто понял механизм, а кто записал слово «экватор».")

    d.h2("1.3 Приёмы, которыми связь устанавливают на уроке")
    d.p("Главный географический приём здесь старый и ничем не заменён: сопоставление карт. В. А. Щенев разбирал приёмы учебной работы по физической географии именно как действия с картой, текстом и профилем, а не как общие лозунги @@shen@@. Для реки рядом кладут физическую карту, климатическую и, если она есть в атласе, карту стока или хотя бы карту бассейнов. Ученик должен увидеть не «ещё одну карту», а ответ на конкретный вопрос. Где в бассейне выпадает осадок и в каком виде. Куда наклонена равнина. Есть ли по дороге горы, озёра, плотины. Пока вопрос не задан, сопоставление превращается в перекладывание атласа.")
    d.p("Остальные приёмы удобнее держать рядом, а не размазывать на пять абзацев. Обратный ход, от странного факта к фактору, нужен там, где прямой рассказ слишком рано всё объясняет: «в низовьях Нила вода поднималась в конце лета, хотя дождя нет». Сравнение работает, только если объекты расходятся в одном главном: Лена и Амур, а не Лена и Енисей, у которых снег общий и различие тонет в мелочах. Прогноз «что будет, если снеговая доля питания упадёт» проверяет механизм, а не мнение о климате. График хода стока учитель может нарисовать сам, но ось нельзя подписывать «тыс. м³/с», если это не данные поста: на рисунке 5 шкала честно названа относительной водностью. И последнее, без чего всё предыдущее рассыпается. Связь не установлена, пока её нет во фразе. Кластер, который класс перерисовал и не может сказать, знанием не становится. Порядок фразы вынесен на рисунок 7: факт, причина, механизм, следствие, граница. Граница — это «для низовья», «до плотины», «не для Европы». В таблицу 1 я не стал класть игру и «квест». Оболочка урока мотива не заменяет: связь появляется, только если ученик сам выбрал фактор и произнёс механизм.")
    d.table(
        "1 — Приёмы работы и то, какую часть связи они закрывают",
        ["Приём", "Что делает ученик", "Где пригодится", "Чего приём не делает"],
        [
            ["Сопоставление карт", "Ищет фактор, который виден на карте, а не в памяти", "Течения и солёность, бассейн реки, мерзлота", "Не заменяет фразу: карта может быть «прочитана» молча"],
            ["От следствия к причине", "Объясняет странный факт, которого бытовая версия не тянет", "Нил в пустыне, сухая Австралия у океана, незамерзающий Мурманск", "Не нужен, если факт классу ещё не странен"],
            ["Пара объектов", "Удерживает один ведущий фактор при сравнении", "Лена и Амур, Конго и Нил, Баренцево и Охотское моря", "Не работает, если реки разные сразу во всём"],
            ["«Что будет, если…»", "Проверяет механизм, меняя условие", "Снег и дождь в питании, сток Волги и уровень Каспия", "Не должен превращаться в спор «о климате вообще»"],
            ["Схема и речь", "Переводит стрелки в предложение со «потому что»", "Любая цепочка, которую оставляем в тетради", "Кластер без устного ответа связи не образует"],
        ],
        widths=[3.2, 4.4, 4.6, 4.3],
    )
    d.p("Отдельно стоит текст учебника. В хорошем параграфе причина часто спрятана в одном предложении, а вокруг лежат цифры, имена путешественников и хозяйственное значение. Ученик, которого учили «найти главное», выделяет цифру: она заметнее. Приём работы с текстом здесь очень конкретный. Карандашом отмечается только фраза, где есть зависимость, и на полях подписывается, что в ней причина, а что следствие. Это медленно и выглядит несовременно. На фоне сплошного конспекта оно как раз и учит читать географию, а не переписывать её @@pan@@.")
    d.note("Дальше в работе примеры рек и цифры расходов даны в школьном приближении: «около», «больше половины», «порядка». Это не замена гидрологическому справочнику. Для урока важна причина и порядок величин, а не спор о третьей значащей цифре.")

    # --- глава 2 ---
    d.h1("2 Система гидрологических знаний в курсах 7 и 8 классов")
    d.h2("2.1 Что именно требует программа")
    d.p("Сначала про рамку, иначе легко учить «свой» 7 класс десятилетней давности. Географии в основной школе отведено 272 часа: по одному часу в неделю в 5 и 6 классах и по два часа в 7, 8 и 9 классах @@fop@@. Гидрология не собрана в один сквозной курс. Она появляется кусками, и методика обязана эти куски сшить, потому что сама программа сшивает их только требованиями к результатам.")
    d.p("В 6 классе гидросфера ещё отдельная тема: круговорот, течения, питание и режим, озёра, лёд, подземные воды, мерзлота, болота. В требованиях прямо сказано устанавливать связь питания, режима и климата бассейна @@fop@@. В кодификаторе ФИПИ то же умение стоит и как метапредметное, и как предметное, привязанное к реке @@fipi@@. Это не пропедевтика «на вырост». Это единственное место, где слова режима вводятся как слова. Если их проскочить, 8 класс начнёт объяснение со словаря.")
    d.p("В 7 классе многочасовой темы «воды суши Земли» уже нет. Есть блок «Мировой океан — основная часть гидросферы», около 6 часов: система течений, их влияние на климат берега, карта солёности и её зависимость от осадков, испарения, рек и льда. Практические работы так и названы, что без связи их не сделать: закономерность солёности и течений у западных и восточных берегов, сравнение двух океанов @@fop@@. Внутренние воды материков спрятаны внутрь раздела «Материки и страны», в формуле «рельеф, климат и внутренние воды и определяющие их факторы». У Евразии в поурочном планировании воды вынуты отдельным уроком, у остальных материков часто сидят внутри общего урока о природе. Здесь, на мой взгляд, дыра курса. Океан собран, его трудно проскочить. Реки материка легко заменить тремя топонимами по дороге к странам. Учителю стоит самому удержать два сильных урока о водах суши: контраст южных материков и Евразию.")
    d.p("В 8 классе гидрология снова одна тема, «Моря России. Внутренние воды и водные ресурсы», тоже около 6 часов: моря как аквальные комплексы, реки и бассейны, опасные явления, роль рек в хозяйстве, озёра, болота, подземные воды, ледники, мерзлота, неравномерность ресурсов и свой регион. Практических работ две: сравнить режим и характер течения двух рек и объяснить распространение опасных явлений @@fop@@. Шесть часов на этот перечень мало. Тема живёт не числом названных рек, а тем, различает ли класс, где в ответе климат, а где рельеф.")
    d.p("Последнее различение я бы повесил на стену кабинета. Режим — про время: когда вода приходит и уходит, чем питается река, когда ледостав. Характер течения — про путь: горная река или равнинная, есть ли пороги, какое падение. У практической работы 8 класса в названии стоят оба слова, и дети их сливают. «Лена спокойная, потому что снеговое питание» — фраза, в которой причина от режима переехала на характер течения. Питание не делает реку равнинной. Равнинной её делает рельеф. Снег делает весенне-летнее половодье. Пока эти две стрелки не разведены, сравнение рек в практической работе остаётся сравнением длины.")
    d.table(
        "2 — Гидрологическое содержание 7 и 8 классов в действующей программе",
        ["Опора сравнения", "7 класс", "8 класс"],
        [
            ["Где лежит в курсе", "Отдельный блок об океане (6 ч) и воды внутри характеристики материков", "Одна тема о морях, внутренних водах и ресурсах (6 ч)"],
            ["Главный масштаб", "Планета, берега материков, контраст континентов", "Территория России и свой край"],
            ["Какая связь обязательна", "Солёность от климата и притока пресной воды; течение и климат берега; воды материка и «определяющие факторы»", "Режим от климата бассейна; характер течения от рельефа; опасное явление как звено цепочки; ресурс и его нехватка"],
            ["Практическая работа", "Закономерность солёности и течений у западных и восточных берегов; сравнение двух океанов", "Режим и характер течения двух рек; распространение опасных гидрологических явлений"],
            ["Чего легко не заметить", "Воды суши растворены в страноведческом материале и пропадают", "Раскраска бассейнов занимает урок, а объяснение режима остаётся дома «по учебнику»"],
        ],
        widths=[3.6, 6.4, 6.5],
    )
    d.p("Учебники эту рамку держат по-разному, и одного «правильного» я здесь не назначаю. «Полярная звезда» собрана уже под действующую программу: воды часто вшиты в образ материка, и учителю приходится самому не дать им раствориться в маршруте по карте @@alek7@@, @@alek8@@. У В. А. Коринской, И. В. Душиной и В. А. Щенева внутренние воды вынуты отдельным разговором, логику объяснения оттуда брать можно, календарь урока — нет, книга от прежней программы @@kor@@. У Е. М. Домогацких и Н. И. Алексеевского вода жёстче по словам: второй автор гидролог @@dom@@. Линия И. И. Бариновой до сих пор лежит в кабинетах 8 класса и удобна тем, что воды легко найти, но климат, пройденный месяцем раньше, сам в параграф не вернётся @@barin@@. Научная гидрология нужна учителю не для лекции, а чтобы не соврать ради простоты. Нельзя, например, называть Гольфстримом любое тёплое течение до самого Мурманска: до Европы доходит уже Северо-Атлантическое течение @@mikh@@. Одна такая оговорка в 7 классе экономит переучивание в 8.")

    d.h2("2.2 Какие связи спрятаны в гидрологическом содержании")
    d.p("Если выписать не объекты, а зависимости, гидрология 7–8 классов складывается в несколько типов. Они повторяются, и это хорошая новость: приём один, меняется территория.")
    d.p("Первый тип — климат и свойства океанской воды. Солёность поверхности растёт там, где испарение сильно, а осадков мало, и падает там, где много дождя, речной воды или тает лёд. Школьная неожиданность, на которой держится проблемный вопрос: на экваторе жарко, но солёность ниже, чем в тропиках, потому что экваториальные дожди опресняют поверхность. Устье Амазонки опресняет океан далеко от берега. Красное море и Персидский залив, если до них доходит разговор, показывают обратное: замкнутость и сухость поднимают солёность сильнее, чем «просто жара». Практическая работа 7 класса как раз про эту карту, плюс про тёплые и холодные течения у разных берегов @@fop@@.")
    d.p("Второй тип — течение и климат берега. В тропиках западные берега материков чаще холодные и сухие, восточные — тёплые и влажные. За холодным берегом иногда стоит не только «пришла холодная вода», но и подъём глубинных вод. Для базового класса слово «апвеллинг» не обязательно, механизм можно сказать по-русски: ветер угоняет поверхностную воду, снизу поднимается холодная, воздух над ней устойчив, дождь выпадает неохотно. Рядом почти всегда есть вторая причина, и её стыдно выбрасывать. У Атакамы холодное Перуанское течение работает вместе с Андами и с тропическим максимумом давления. Если оставить в ответе только течение, мы своими руками учим той самой однопричинности, от которой хотим избавиться. Честная школьная фраза: ведущий фактор, который просит практическая работа, — течение, рельеф сухость усиливает.")
    d.figure(
        "currents",
        "Рисунок 3 — Течения у берегов: тропическое правило и оговорка про Северную Атлантику",
    )
    d.p("Оговорка на рисунке 3 для меня важнее самого правила. Правило «западный берег холодный» в тропиках работает и проверяется работой. В умеренных широтах Европы оно врёт. Баренцево море у Мурманска зимой не становится сплошным льдом именно потому, что сюда доходит тёплая атлантическая вода. Если семиклассник унесёт с урока заклинание без оговорки, в 8 классе учитель будет не объяснять моря России, а ломать собственную схему. Проще потратить пять минут в 7 классе.")
    d.p("Третий тип — рельеф и характер течения, границы бассейна, пороги, направление стока. Водораздел, порог, горная и равнинная река известны с 6 класса, но причинную работу они начинают делать позже. В Африке водопады и пороги — следствие того, что реки сходят с поднятий и прорезают твёрдые породы, а не «достопримечательность». В России характер течения Терека и Волги нельзя сравнивать, глядя только на климат Кавказа и Русской равнины. Терек быстрый, потому что падение большое. Волга равнинная, даже если в верховьях она живее, чем у дельты.")
    d.p("Четвёртый тип — главный для обеих классов: климат бассейна → источник питания → режим. Дождь, снег, ледники, подземные воды редко бывают в одиночку, и школьный ответ обычно называет ведущий источник, а не единственный. У Амазонки ведущее питание дождевое. Бассейн лежит и к северу, и к югу от экватора, сезоны дождей у притоков не совпадают, поэтому долгой низкой воды, знакомой по рекам с одним сезоном, нет. Конго дважды пересекает экватор, и ровный ход года там тоже не случайность. Это как раз тот механизм, который стоит рисовать, а не заменять фразой «экваториальные реки полноводны всегда».")
    d.p("Нил устроен интереснее и потому ценнее для методики. Белый Нил с экваториальных озёр даёт более ровную долю, Голубой Нил с Эфиопского нагорья приносит летние дождевые воды и раньше задавал паводок в сухом Египте. Река транзитная: место, где виден высокий уровень, и место, где сформировалась вода, не совпадают. Асуанская плотина этот природный ход в низовье изменила. На уроке нужны два слоя, двумя цветами мела или двумя строками схемы. Один слой — природа, второй — человек. Склеивать их в «Нил теперь такой, потому что климат Египта» нельзя.")
    d.p("Пятый тип — бессточные котловины и происхождение озёр. Эйр, Чад и Каспий замкнуты рельефом, и испарение там съедает сток. Байкал глубок, потому что это рифт, а не потому что «горы высокие» и не потому что его выпахал ледник: ледниковыми в школьном курсе честнее называть Ладогу и Онего. Каспий по происхождению остаточный морской водоём, отсюда и солёность. Короткой развилки «тектонические, ледниковые, остаточные, запрудные» восьмикласснику хватает, если за каждым словом стоит причина, а не оценка за термин.")
    d.p("Шестой тип — мерзлота, болота, лёд. Мерзлота занимает около двух третей площади России. Она не создаёт реки: она не пускает воду под землю, срезает зимнее подземное питание и вместе с плоским рельефом держит болота. Антарктида ломает шаблон «у материка есть реки». Осадки выпадают снегом, таяния почти нет, сток идёт льдом к берегу, дальше обламываются айсберги. Жидкие водотоки там исключение. Тратить материк на рекорды толщины льда жалко: рекорд не объясняет, куда девается осадок.")
    d.figure(
        "chains",
        "Рисунок 4 — Три цепочки «откуда вода и когда она приходит»: Амазонка, Нил, Амур",
    )
    d.p("Седьмой тип — опасное явление как последнее звено цепочки, а не список «стихийных бедствий» в конце параграфа. Затор на Лене, Северной Двине, Печоре получается там, где волна половодья бежит на север, в ещё не вскрывшийся лёд. Летний подъём Амура — из дождей, не из апреля. Сель — крутой склон, рыхлый материал и резкая вода. Нагон на Неве — ветер из залива: сама Нева короткая, Ладога как раз сглаживает её питание. Если причину отрезать, вторую практическую работу 8 класса выполнять нечем.")
    d.p("Восьмой тип — хозяйство, и программа сама кладёт его в те же шесть часов. Подменять природную связь он не должен. Водохранилища Волги срезают пик половодья, но ведущее питание по-прежнему снеговое, около 60 %, подземное около 30 %, дождевое около 10 % @@mikh@@. Каспий получает от Волги порядка четырёх пятых речной воды, поэтому многолетний уровень связан со стоком и с испарением, а не с одной ГЭС. В XX веке уровень и падал, и рос. Для базового класса хватает двух фраз: снег задаёт природный ход, плотины меняют его форму, до моря доходит уже остаток.")
    d.table(
        "3 — Режим нескольких рек, на которых удобно учить связь, а не номенклатуру",
        ["Река", "Ведущее питание", "Когда воды больше", "Какую ошибку ждать"],
        [
            ["Амазонка", "Дождевое", "Высокая вода держится большую часть года", "«Полноводна, потому что длинная и из-за леса»"],
            ["Конго", "Дождевое", "Ход ровный: бассейн дважды пересекает экватор", "Путают с Нилом и ищут один паводок"],
            ["Нил", "Дождевое, транзитное", "Раньше паводок в низовье в конце лета; сейчас ход изменён плотиной", "Причину ищут в климате пустыни вокруг русла"],
            ["Волга", "Снеговое", "Весеннее половодье, сглаженное каскадом", "Называют ледники Кавказа или «дожди»"],
            ["Лена", "Снеговое", "Конец весны и начало лета, заторы в среднем и нижнем течении", "Считают её горной рекой «потому что Сибирь»"],
            ["Амур", "Дождевое", "Вторая половина лета и осень", "Ждут апрель, как у «всех российских рек»"],
        ],
        widths=[2.6, 3.4, 5.3, 5.2],
    )
    d.figure(
        "hydro",
        "Рисунок 5 — Качественный ход водности Амазонки, Лены и Амура в течение года",
    )
    d.p("Расход в таблицу 3 я сознательно не ставил. Учителю полезно помнить порядок: Енисей, Лена и Обь по стоку крупнее Волги, хотя в хозяйственном рассказе Волга «главнее». Ученику сначала нужны месяц и источник воды. Рисунок 5 для этого и сделан. Его лучше показывать как задачу: закрыть подписи и спросить, какая кривая не может быть сибирской рекой со снеговым питанием. Заодно снимается привычка переносить свой январь на экватор. У Амазонки нет холодного сезона, который копил бы снег, поэтому и провала «зимой» нет.")

    d.h2("2.3 Как знание нарастает от 6 класса к 8")
    d.p("Преемственность здесь не лозунг из пояснительной записки, а очень конкретный список слов, которые в 8 классе уже некогда вводить заново. Из 6 класса должны дойти: питание, режим, бассейн, водораздел, половодье, паводок, межень, тёплое и холодное течение, сточное и бессточное озеро. Если их нет, урок про Лену превращается в словарь, и до затора вы не дойдёте. Я бы в начале темы океана в 7 классе и в начале вод России в 8 классе оставлял короткий вход на 7–8 минут: не опрос ради оценки, а три вопроса, чтобы понять, можно ли сегодня говорить о причине. Например: чем питание отличается от режима; почему у одной реки два половодья бывают редко, а один сезон высокой воды — часто; какое течение тёплое, то, что течёт из жары, или то, что теплее окружающей воды. Последний вопрос стабильно снимает ошибку.")
    d.figure(
        "continuity",
        "Рисунок 6 — Наращивание гидрологических связей от 6 класса к 8",
    )
    d.p("Новое в 7 классе, если слова режима уже есть, — не термин, а усложнение. Несколько климатов внутри одного бассейна. Система течений и её следствие для берега, вместе с европейским исключением. Транзитная река, у которой низовье живёт чужим климатом. Объяснение, почему океан не спасает внутреннюю Австралию: пояс высокого давления, холодное течение на западе, хребет держит влагу на востоке. Для сильных одна оговорка: Большой Артезианский бассейн существует, «сухо на поверхности» не значит «воды нет нигде». Новое в 8 классе — уже своя страна. Континентальность к востоку, муссон Дальнего Востока, мерзлота как массовое условие, регулирование стока и парадокс ресурсов: воды больше на севере и востоке, а люди исторически сели на юго-западе, где теплее почвы, а не где полноводнее Енисей @@fop@@, @@alek8@@. Этот стык программа спрашивает в той же теме, что и режим.")
    d.p("Свой край здесь нельзя описать до конца: река у каждого своя. Шаблон короткий. Источник питания по климату области, одна человеческая поправка, одно опасное явление именно этой реки, а не «наводнения вообще». Четыре пункта закрывают строку программы и проверяют, не прилипло ли умение к Волге. Разрывы, из-за которых схема сыпется, тоже лучше назвать заранее. Слабый 6 класс заставляет возвращать питание и режим, иначе течения повиснут в пустоте. Ложная непрерывность — начать 8 класс сразу с ГЭС, без режима. И наш собственный разрыв: в 7 классе упростить течение до ошибки, а в 8 классе требовать точности.")

    # --- глава 3 ---
    d.h1("3 Методика формирования знаний на гидрологическом материале")
    d.h2("3.1 Из каких шагов состоит работа на уроке")
    d.p("Методика, которую я предлагаю, не претендует на новое имя. Это сборка уже известных приёмов под конкретный кусок программы и под часы, которые на него даны. Принципов немного, и каждый из них появился не из любви к спискам, а из типичного срыва.")
    d.p("Первый принцип: идти от связи, которая уже есть, к связи, которой ещё нет. В 8 классе нельзя начинать так, будто слово «питание» родилось сегодня. Второй: за урок доводить до устной фразы одну цепочку, а не пять. Остальные идут по аналогии, иначе ничего не доводится. Третий: связь, которую нельзя показать на карте или на простой схеме, для этого возраста лучше упростить или отложить. Четвёртый: причина и следствие называются разными словами, и учитель хотя бы раз за урок спрашивает «что здесь причина?», даже если ответ кажется очевидным. Пятый: проверка делается на объекте, которого не разбирали вместе. Шестой: свой край не вместо большой реки, а как перенос. Если краеведение подменяет Лену и Амур, страна так и остаётся набором картинок.")
    d.p("Отсюда этапы одного урока, не всей темы. Сначала вопрос, на котором бытовая версия ломается. Не «сегодня мы изучим режим рек», а «почему Амур выходит из берегов в августе, хотя снег давно сошёл». Потом короткая опора: какие вообще бывают источники воды и чем режим отличается от характера течения. Это пять минут, не новый параграф. Потом одна цепочка собирается на доске словами класса, не монологом. Потом фраза записывается в тетрадь в порядке формулы с рисунка 7. Потом пара работает со второй рекой по той же формуле, уже без пошаговой диктовки. В конце — объект, которого не было в паре, или вопрос «что будет, если». Домашнее, если оно нужно, не «перескажи параграф», а дострой такую же цепочку для реки своего края или для реки, названной учителем, по картам атласа.")
    d.figure(
        "formula",
        "Рисунок 7 — Порядок устного и письменного объяснения, к которому возвращаются оба курса",
    )
    d.p("Учительский конспект при такой схеме толще ученической записи. В нём заранее лежат не только факты, но и ответы, которые класс наверняка предложит. Это самая нелюбимая часть подготовки, и она же самая полезная. Если вы не предполагаете, что Волгу накормят ледниками Кавказа, вы услышите это в лучшем случае от одного смелого ученика, а остальные тихо с ним согласятся. Ниже, в сюжетах 7 и 8 класса, я как раз пишу ожидаемые сбои рядом с ходом урока. Без этой колонки методика выглядит глаже, чем живой урок, и студенту на практике от неё мало толку @@fin@@, @@pan@@.")

    d.h2("3.2 Седьмой класс: океан и воды материков")
    d.p("Первый сюжет — практическая работа про солёность и течения. Я бы не делал из неё отдельный «урок оформления». Сначала проблема. Две точки примерно на одной широте: побережье Намиба и восточный берег Мадагаскара, или Лима и берег Бразилии на сопоставимой широте. Климат разный, хотя «солнце одно и то же». Первый ученический ответ часто про горы. Его не надо высмеивать. В Южной Америке Анды действительно запирают влагу, и это часть правды про Атакаму. Дальше открывается карта течений. У западного берега холодное течение, у восточного тёплое. Вопрос: какая стрелка объясняет сразу оба берега, а какая только усиливает сухость там, где есть горы? Так практическая работа становится ответом на спор, а не таблицей «выпиши течение».")
    d.p("Дальше класс смотрит уже не климат берега, а саму солёность, чтобы не смешать две разные связи в одну. Вопрос-ловушка: где вода солонее, на экваторе или в тропиках, если на экваторе жарче? Кто думает только про испарение, тычет в экватор. Карта солёности этого не подтверждает: экваториальные дожди опресняют поверхность, а в тропиках при ясном небе испарение выигрывает у осадков. Рядом, если остаётся время, устье Амазонки: пресная вода реки заметна в океане. Здесь связь уже не «климат точки», а «река вмешивается в океан». Для сильного ученика это заготовка под 8 класс, где Обь и Енисей так же опресняют свои заливы, только в холодном варианте.")
    d.p("Отдельные пять минут — Европа и Мурманск, даже если практическая работа формально про материки тропиков. Я уже объяснял зачем. Коротко: найти на карте течений продолжение атлантической системы к северу, сравнить с восточным берегом Северной Америки на той же широте, сказать одну фразу. «Правило западного и восточного берега мы берём для тропиков. На севере Атлантики тёплая вода приходит к западу Европы». Записать эту фразу. В 8 классе на Баренцевом море её не придётся добывать заново, достаточно будет напомнить.")
    d.p("Второй сюжет 7 класса — воды материка, и здесь я беру не «все материки по очереди», а один контраст, который можно успеть. Южная Америка и Австралия в программе стоят в одном разделе южных материков, и они спорят друг с другом почти идеально @@fop@@, @@alek7@@.")
    d.p("По Амазонке не пересказываю механизм второй раз: он уже собран на рисунке 4 и в таблице 3. На уроке важен вопрос, которого нет в готовом абзаце. Если бы все крупные притоки лежали только к югу от экватора, появился бы общий сезон низкой воды или нет? Кто отвечает «всегда одинаково, она же экваториальная», ещё держится за ярлык пояса. Ответ «из-за сельвы» и ответ «из-за ледников Анд» приходят сами, их надо снять в ту же минуту: лес — следствие увлажнения, ледники для Амазонки не ведущий источник, в отличие от Терека. Австралия строится встречным вопросом: почему океан рядом не делает внутренние районы Амазонией? Базовому классу оставляю два фактора, пояс давления и барьер хребта. Течение добавляю тем, кто уже закрыл практическую работу по берегам. Три разных карточки «для слабых» здесь не нужны.")
    d.p("Нил в тот же урок не ставится. На нём учится другое: транзитность. Пятнадцать минут внутри темы Африки хватает, если не уходить в перечень водопадов. Где дождь, где люди ждали воду, когда она приходила, что изменила плотина. Два слоя, как на рисунке 4. Евразия ближе к 8 классу: Ганг и Меконг готовят летний Амур, бессточные реки и Арал готовят Каспий. По Аралу одна жёсткая оговорка. Климат и раньше был сухим, но современное отступание берега — в основном разбор воды на орошение. Смешивать «всегда было сухо» и «воду разобрали» нельзя. Антарктиду, если она рядом по календарю, закрываю связью про ледовый сток, а не рекордом толщины льда.")
    d.p("Как понять, что 7 класс сработал, ещё до контрольной. Ученик по карте течений говорит, какой берег в тропиках суше и почему, и сам добавляет, что для Европы правило другое. По Амазонке произносит «дождь» и «оба полушария», а не «лес» и «длина». По Нилу показывает рукой на нагорье, а не на пустыню вокруг долины. Это три фразы. Если их нет, практическая работа, сданная в виде таблицы течений, учителя успокаивает зря.")

    d.h2("3.3 Восьмой класс: воды России за шесть часов")
    d.p("Шесть часов я бы не дробил на двенадцать «маленьких тем». Дробление как раз съедает связь: сегодня номенклатура рек, завтра номенклатура озёр, послезавтра болота, и нигде нет времени спросить «почему». Ниже один из возможных раскладов. Он не единственный, но в нём у каждой пары часов есть своя цепочка, а не свой список.")
    d.p("Первый час — три моря, не двенадцать. Баренцево теплее своей широты из-за атлантической воды: сюда возвращается оговорка 7 класса. Охотское остаётся холодным и тяжёлым по льду, Куросио его не «спасает». Чёрное тёплое; сероводород в базовый урок я бы не тащил. Связь одна: широта и обмен с океаном задают температуру и лёд. Второй час — бассейны и вопрос после раскраски. К Северному Ледовитому уходят Обь, Енисей и Лена, к Тихому — Амур, Волга уходит в Каспий, а не «в Атлантику». Цвет на карте работой не считается. Вопрос после него: почему к северу уходит столько воды, а жизнь страны сложилась не на Нижней Тунгуске? И сразу снять формулу «все реки России текут на север»: Нева, Волга, Амур и Кубань её ломают. На север текут великие сибирские, и это важно для заторов, но это не закон страны.")
    d.p("Третий и четвёртый часы — режим и характер течения, практическая работа. Пару я беру Лену и Амур, не Волгу и Енисей. Волга и Енисей оба в основном снеговые, различие тоньше, его лучше оставить сильной группе вторым примером. Лена и Амур расходятся в самом источнике воды, и ошибка «все наши реки разливаются в апреле» умирает на их графике.")
    d.p("Сами цепочки Лены и Амура уже лежат в таблице 3 и на рисунке 5, заново их не диктую. На уроке ловлю другое. По Лене кто-нибудь скажет «горная, потому что Сибирь»: тогда открываем среднее и нижнее течение и отдельно исток, чтобы слово «равнинная» получило границу. По Амуру класс попробует скопировать снег «только снега меньше». Здесь стоп и возврат к карте осадков по сезонам, а не к карте «где холоднее». Холод есть в обоих бассейнах. Если графа «характер течения» у двух рек выйдет похожей, а графа «режим» — нет, это удача: две графы практической работы наконец живут отдельно. Подъём 2013 года можно узнать на фотографии, но не делать из него определение реки.")
    d.p("Волгу оставляю пятым часом, уже как усложнение, не как «главную реку с первой минуты». Базовому классу две строки: снег задаёт ход, каскад меняет форму хода. Сильному — вопрос про Каспий: несколько маловодных лет и высокое испарение опустят уровень и при тех же плотинах. Байкал в этот же кусок времени легко превращается в слово «уникальный». Держу причину глубины, рифт, и одну связь, которую рекорды заслоняют: Ангара вытекает из огромного озера и поэтому спокойнее соседних рек без такого водоёма. Эндемиков, если часы трещат, честнее отдать биологии.")
    d.p("Болота Западной Сибири — обязательный многопричинный пример, даже если на него остаётся половина часа. Плоский рельеф, превышение осадков над испарением, слабый сток, глинистые грунты, на севере мерзлота, долгий разлив Оби. Плюс обратная петля: болото само затрудняет дренаж. Рисунок 8 для доски. Вопрос не «есть ли болота», а «почему вода не уходит». Ответ «потому что много воды» учитель не принимает, это круг. Сравнение с чем-то более расчленённым, хотя бы с Валдаем, помогает: вода есть и там, а сплошного Васюганья нет, потому что уклон другой.")
    d.figure(
        "swamp",
        "Рисунок 8 — Почему вода не уходит: несколько причин заболоченности Западной Сибири",
    )
    d.p("Последний час я бы отдал ресурсам и опасностям вместе, иначе опасность снова оторвётся от причины. Сначала карта: где воды много, где её не хватает относительно хозяйства. Юг Русской равнины и степь живут в дефиците, север и Сибирь — в избытке стока при недостатке людей. Мера должна попадать в причину. «Построить очистные» — ответ на грязную воду, а не на реку, которая в августе пересыхает в степи. «Сделать водохранилище» может выравнивать режим, но не лечит солёность и не заменяет экономию, если воду разбирают на поля. В таблице 4 это разведено специально грубо, чтобы на уроке можно было дать карточку «выбери меру, которая бьёт в причину, и вычеркни меру, которая про другое».")
    d.table(
        "4 — Мера имеет смысл только если она про ту же причину, что и беда",
        ["Что не так", "В чём причина", "Мера попадает в причину", "Мера мимо, хотя звучит «экологично»"],
        [
            ["Летние наводнения на Амуре", "Дождевое питание, затяжные дожди", "Прогноз, дамбы, запрет стройки в низкой пойме", "Борьба с весенним снегом, которого в пике нет"],
            ["Заторы на Лене", "Волна половодья идёт на север, в лёд", "Ледокольные и взрывные работы по регламенту, зонирование, а не «отмена снега»", "Очистные сооружения"],
            ["Дефицит воды на юге", "Много испарения, большой разбор, мало стока", "Учёт воды, смена культур, повторное использование", "Лозунг «у нас в стране воды много» со ссылкой на Байкал"],
            ["Грязная вода у города", "Сброс без очистки", "Очистка и контроль сброса", "Новая плотина выше по течению"],
            ["Нагон на Неве", "Ветер нагоняет воду залива", "Дамба и прогноз, понимание, что это не половодье", "Объяснение «в Ладоге растаял снег»"],
        ],
        widths=[3.4, 4.0, 4.6, 4.5],
    )
    d.p("Свой край в этот час входит коротким шаблоном из четырёх пунктов, о котором я писал во второй главе. Если школа стоит на равнинной реке снегового питания, ученик должен узнать в ней «волжский» тип, а не начинать описание с нуля в восторге, что река местная. Если школа на Кубани или Тереке, ведущим может оказаться ледниково-снеговое питание и горный характер течения, и тогда сравнивать родную реку надо не с Леной, а с горной парой. Методика переноса как раз в том, чтобы выбрать аналог, а не любимую реку учебника.")
    d.p("Фрагмент урока, где сравниваются Лена и Амур, расписан по минутам в приложении А. Здесь я перескажу только место, на котором урок обычно провисает. Это переход от первой реки ко второй. Учитель так хорошо объяснил Лену, что Амур дети тоже начинают кормить снегом, только «в Сибири снега больше, на Дальнем Востоке меньше». Приходится останавливаться и возвращать карту осадков по сезонам, а не карту «где холоднее». Холод есть в обоих бассейнах. Различает их не январская температура сама по себе, а то, в каком виде и в каком месяце приходит основная вода. Если этот переход проговорён, дальше Колыма в проверке почти не нуждается в подсказке: она «лениного» типа. Если переход проглочен, Колыма в ответе тоже станет «дождевой», потому что лежит на востоке. Восток страны у подростка легко слипается в одно пятно.")

    d.h2("3.4 Задания, ошибки и как понять, что связь есть")
    d.p("Проверять эту тему пересказом параграфа бессмысленно. Пересказ награждает память. Связь видна в четырёх видах задания, и они не обязаны все попадать в одну контрольную. Первый вид — достроить цепочку, где два звена уже даны. «Климат бассейна Лены… → питание… → месяц высокой воды… → чем это опасно в среднем течении». Это ещё полурепродукция, зато видно, на какой стрелке дыра. Второй вид — объяснить изученную реку без схемы перед глазами, устно, по формуле. Третий — перенос: Колыма после Лены, Меконг после разговора о муссоне, крик Австралии после разговора о внутреннем стоке. Четвёртый — испорченная причина. Учитель даёт фразу, в которой причина и следствие поменяны местами или подменено соседним фактом, и просит починить. «Амазонка полноводна, поэтому в её бассейне экваториальный климат». Климат и река здесь стоят не в ту сторону. Такие фразы дети сначала не узнают, потому что все слова знакомые и «про географию».")
    d.table(
        "5 — Задания по нарастающей самостоятельности",
        ["Уровень", "Пример", "Что считается удачей"],
        [
            ["Достроить", "Закончите цепочку про Амур: летние дожди → … → …", "Названы дождевое питание и летне-осенний подъём, а не «весна»"],
            ["Объяснить изученное", "Почему половодье Волги весеннее, даже если в низовьях летом жарко?", "Причина уведена в бассейн и в снег, низовье не назначено источником"],
            ["Перенести", "Колыму в классе не разбирали. Какой из двух графиков, ленский или амурский, ей ближе и почему?", "Выбран снегово-северный тип, есть слово про мерзлоту или затор"],
            ["Починить причину", "«Байкал глубокий, потому что в нём чистая вода». Исправьте.", "Глубина связана с рифтом, чистота не названа причиной глубины"],
            ["Прогноз", "Несколько малоснежных зим подряд и тот же каскад ГЭС. Что изменится в половодье Волги?", "Пик станет ниже из-за снега; плотина не названа единственной причиной"],
        ],
        widths=[3.2, 7.3, 6.0],
    )
    d.p("Оценку я бы не притворял точным измерителем. Для формирующей проверки достаточно трёх состояний. Не собрано: ученик называет объект и одну случайную причину, путает режим с характером течения. Собрано с опорой: по схеме или по наводящему вопросу цепочка звучит верно, перенос ещё шаткий. Собрано: фраза есть без схемы, на новой реке ведущий фактор выбран не по сходству названия, граница «где это верно» хотя бы намечена. Ставить за это отдельную «пятёрку по причинности» в журнал не нужно. Нужно, чтобы практическая работа 8 класса принималась не по раскрашенной карте, а по пяти строкам, где у двух рек отдельно написаны режим с причиной и характер течения с причиной. Карта бассейнов может быть приложением, не доказательством понимания.")
    d.table(
        "6 — Ошибки, которые стоит ждать заранее, а не «разбирать, если вдруг»",
        ["Как звучит ответ", "В чём сбой", "Короткий ход учителя"],
        [
            ["«Река большая, поэтому полноводная»", "Размер выдан за причину", "Спросить про расход маленькой горной реки в паводок и про пересыхающий крик большой длины"],
            ["«Все реки России разливаются весной»", "Опыт европейской части перенесён на всю страну", "Открыть ход Амура и календарь муссона"],
            ["«Лена горная, она же в Сибири»", "Рельеф подменён «суровостью»", "Показать среднюю и нижнюю Лену на физической карте, отдельно исток"],
            ["«Западный берег всегда холодный»", "Тропическое правило потеряло границу", "Мурманск и карта Северо-Атлантического течения"],
            ["«Болота, потому что много воды»", "Круг в определении", "Вопрос «почему вода не стекает», рисунок 8"],
            ["«Каспий сохнет из-за ГЭС»", "Один хозяйственный объект вместо стока и испарения", "Доля волжской воды и факт, что уровень в XX веке ещё и рос"],
            ["«Наводнение на Неве — половодье»", "Смешаны нагон и режим реки", "Ладога сглаживает сток; воду поднимает ветер залива"],
        ],
        widths=[5.0, 5.5, 6.0],
    )
    d.p("Таблица 6 — это, по сути, колонка для конспекта, а не материал для раздачи детям целиком. Раздавать список ошибок до урока опасно: слабый ученик запоминает ошибку лучше правила, особенно если она короче. Разбирать ошибку лучше в ту минуту, когда она прозвучала, и сразу возвращать к карте. Если не прозвучала ни разу, одну-две всё равно стоит предложить в задании «почини фразу». Иначе учитель так и не узнает, живы ли они в тетрадях.")
    d.p("Цифру без причины в ответ я бы не ставил выше месяца половодья. Длину ученик доберёт, механизм сам не появится. Задания с коротким эталоном лежат в приложении Б. Лучше разбирать по одному в конце часа, пока связь тёплая, чем копить всё к контрольной через две недели: там причины снова смешаются, и покажется, что не сработал урок, хотя сработало обычное забывание.")

    d.h2("3.5 Что изменится в подготовке учителя")
    d.p("Если собрать главу к практическому выводу, подготовка к теме становится другой. Раньше студент на практике часто готовит «ход урока»: опрос, новый материал, закрепление, и в новый материал кладёт пересказ параграфа с презентацией рек по фотографиям. В логике этой работы конспект начинается с другой стороны. Сначала выбирается одна связь, которую к концу урока должны произнести вслух даже не самые смелые. Потом под неё подбирается пара объектов. Потом выписываются два-три ошибочных ответа, которые жалко будет упустить. Потом только презентация, и в ней меньше видов с вертолёта и больше двух карт и одной схемы. Фотография затора нужна, но после схемы, иначе она остаётся картинкой беды без причины.")
    d.p("Учебник при этом не враг. В «Полярной звезде» воды материка надо успеть вынуть из общего очерка, пока урок не ушёл в население @@alek7@@. У Коринской, Душиной и Щенева, наоборот, нельзя прочитать весь удобный параграф только потому, что он так называется @@kor@@. «Не успели» часто значит «не выбрали». И эта курсовая пробный урок не заменяет. Я не услышу, как конкретный класс кормит Амур снегом, и не пишу, что методика «доказала эффективность». Бодрый урок с раскраской бассейнов и бодрый урок, где прозвучала фраза про муссон, снаружи похожи. Различаются они тетрадкой.")

    # --- заключение ---
    d.h1("Заключение")
    d.p("Работа начиналась с довольно приземлённого наблюдения: реки в 7 и 8 классе знают по имени чаще, чем по причине. Дальше нужно было понять, что с этим делать в рамках действующей программы, а не в рамках идеального курса, где на гидрологию отведена четверть.")
    d.p("Связь в работе отделена от факта, от простого соседства на карте и от хозяйственной поправки, которая природный ход не отменяет. Для 13–15 лет рабочая длина цепочки — несколько звеньев, с картой и с правом сначала собрать её вместе. Шесть часов океана в 7 классе и шесть часов вод России в 8 классе заставляют выбирать. Воды материков программа растворила в характеристике континентов, и контраст Амазонки, Нила и Австралии учитель удерживает сам. В 8 классе главная развилка — не спутать режим и характер течения: первое от климата бассейна, второе от рельефа. Ход урока из этого получается короткий. Слом бытового объяснения, опора на 6 класс, одна цепочка до фразы, вторая река в паре, перенос на объект, которого не разбирали. Удача — фраза со «потому что» на новой реке, а не пересказ абзаца.")
    d.p("Ограничения честные. Я не проводил эксперимента и не имею права писать, на сколько процентов выросло умение. Региональный пример дан шаблоном, потому что река читателя этой работы мне неизвестна. Расходы и доли питания приведены как школьный порядок величин, их не надо переносить в отчёт по гидрологии как результат измерения. Часть учебников названа не как единственно верные, а как книги, в которых по-разному спрятана одна и та же связь.")
    d.p("На практику я бы взял из работы три вещи, не весь текст. Формулу ответа: факт, причина, механизм, следствие, граница. Пару Лена — Амур с качественным графиком, у которого не соврана ось. И список ожидаемых ошибок на полях конспекта. Если эти три вещи попадут в один пробный урок, курсовая сделала то, что должна была: не заменила учителя, а не дала ему потратить шесть часов на номенклатуру, которую класс и так запоминает легче, чем причину.")

    d.bibliography()
    write_appendix_a(d)
    write_appendix_b(d)


def write_appendix_a(d: Paper):
    d.h1("Приложение А", page_break=True)
    d.p("Технологическая карта урока", align="center", indent=0, bold=True, before=0, after=6)
