def build(toc_pages, path):
    figs = build_all()
    paper = Paper(figs, toc_pages)
    write_title(paper)
    write_task(paper)
    paper._new_section()
    # Содержание будет заполнено после того, как toc собран, поэтому сначала тело
    # пишем во временный документ нельзя без двойной генерации.
    # Здесь: собираем тело в тот же документ ПОСЛЕ содержания нельзя, если TOC
    # должен стоять впереди. Делаем два документа нельзя проще, чем:
    # сначала прогон тела в черновик для списка заголовков, потом полный.
    paper.save(path)  # заглушка, реальный порядок ниже
    return paper


def assemble(toc_pages):
    figs = build_all()
    # Черновой прогон только чтобы знать заголовки? Они стабильны.
    # Полный документ: титул, задание, новый раздел, содержание, тело.
    paper = Paper(figs, toc_pages)
    write_title(paper)
    write_task(paper)
    paper._new_section()
    # Заголовки тела нужно знать до печати содержания.
    # Печатаем содержание после предварительного сбора toc через сухой вызов? 
    # Проще: сначала собрать toc отдельным проходом без save, но write_body
    # пишет в документ. Поэтому разделим: 
    # 1) черновой Paper, write_body, забираем toc, документ выбрасываем
    # 2) чистовой Paper с готовым словарём страниц и уже известным toc — нет,
    #    toc наполняется в write_body.
    # Порядок в чистовом: write_body должен идти ДО toc_page, затем мы
    # переставляем элемент содержания? Сложно в oxml.
    # Делаем черновик для toc-списка не нужен, список стабилен.
    # В чистовом документе: toc_page печатается первым в разделе 2,
    # но titles ещё не собраны.
    #
    # Решение: write_body на черновике, копируем список toc (тексты),
    # затем чистовой документ печатает toc_page из сохранённого списка.
    draft = Paper(figs, toc_pages)
    write_body(draft)
    titles = list(draft.toc)
    paper.toc = titles
    paper.toc_page()
    write_body(paper)
    out = ROOT / "kursovaya.docx"
    paper.save(out)
    return out


def extract_pages(pdf_path):
    import subprocess
    txt = ROOT / "_pages.txt"
    subprocess.check_call(["pdftotext", "-layout", str(pdf_path), str(txt)])
    raw = txt.read_text(encoding="utf-8", errors="replace")
    pages = raw.split("\f")
    return pages


def heading_page(pages, title):
    needle = " ".join(title.split())[:48]
    # Страницы 1–3: титул, задание, содержание. Заголовок раздела ищем дальше.
    for i, page in enumerate(pages, 1):
        if i <= 3:
            continue
        if needle in " ".join(page.split()):
            return i
    return None


def main():
    import subprocess
    out = assemble({})
    pdf = ROOT / "kursovaya.pdf"
    subprocess.check_call(
        ["soffice", "--headless", "--convert-to", "pdf", "--outdir", str(ROOT), str(out)],
        stdout=subprocess.DEVNULL,
    )
    pages = extract_pages(pdf)
    # Заголовки берём из повторной сборки через чтение toc невозможно.
    # Собираем карту по известным началам заголовков из документа: прогоним titles.
    draft_pages = {}
    # Список заголовков восстановим, собрав ещё раз всухую.
    figs = build_all()
    draft = Paper(figs, {})
    write_body(draft)
    found = {}
    missing = []
    for _level, title in draft.toc:
        n = heading_page(pages, title)
        if n is None:
            missing.append(title)
        else:
            found[title] = n
    print("PDF pages:", len(pages))
    print("TOC mapped:", len(found), "of", len(draft.toc))
    for t in missing:
        print("MISSING", t)
    for t, n in found.items():
        print(f"{n:3}  {t}")
    # Вторая сборка с номерами
    assemble(found)
    subprocess.check_call(
        ["soffice", "--headless", "--convert-to", "pdf", "--outdir", str(ROOT), str(ROOT / "kursovaya.docx")],
        stdout=subprocess.DEVNULL,
    )
    pages2 = extract_pages(pdf)
    print("FINAL PDF pages:", len(pages2))
    # Проверка, что номера не уехали
    draft2 = Paper(figs, found)
    write_body(draft2)
    bad = 0
    for _level, title in draft2.toc:
        n = heading_page(pages2, title)
        if n != found.get(title):
            bad += 1
            print("SHIFT", found.get(title), "->", n, title)
    print("shifts", bad)
    # Содержание входит в объём. Титул + задание = 2 страницы.
    content_pages = len(pages2) - 2
    print("content pages (without title and task):", content_pages)


if __name__ == "__main__":
    main()
